import React from "react";

interface TMLogoProps {
  size?: number;
  className?: string;
}

// Logo is embedded as base64 — no file path or CDN dependency.
// The actual TM circular seal, always available on every environment.
const LOGO_B64 = "data:image/png;base64,";

export default function TMLogo({ size = 40, className = "" }: TMLogoProps) {
  return (
    <img
      src={LOGO_B64}
      alt="ታማኝ ማሽነሪ — Trustworthy Machinery (TM)"
      width={size}
      height={size}
      className={`rounded-full object-cover ${className}`}
      style={{ width: size, height: size, minWidth: size }}
    />
  );
}
